/****************************************************************************
 * board/beken/boards/bk7258/bk7258-ap/src/bk7258_i2c1_gpio_diag.c
 *
 * Minimal GPIO-level diagnostic for the GC2145 I2C1 bus (GPIO42=SCL,
 * GPIO43=SDA), bypassing the I2C1 hardware peripheral entirely.
 *
 * Context: bk7258_i2c1_write_reg() consistently times out waiting for the
 * I2C1 interrupt (sm_int never fires), even though sm_bus_cfg reads back
 * exactly as configured (EN=1, FREQ_DIV=84, CLK_SRC=3, etc. -- register
 * programming confirmed correct).  START bit is set but no state-machine
 * interrupt ever follows -- consistent with "the bus is electrically
 * silent" rather than a software/register misconfiguration.
 *
 * This diagnostic reconfigures GPIO42/43 as plain GPIO outputs (undoing
 * the I2C1 pinmux function selection) and manually toggles them to
 * produce an I2C-like START condition + a few clock pulses, entirely
 * under direct software control.  The purpose is to let a logic
 * analyzer/oscilloscope confirm or rule out, independently of the I2C1
 * hardware block, whether these two physical pins can be driven at all:
 *
 *   - If no activity is observed on GPIO42/43 even in this GPIO bit-bang
 *     mode: the pinmux routing itself is not reaching the physical pins
 *     (wrong pin numbers, wrong function index, or a hardware/soldering
 *     issue on this board), independent of the I2C1 peripheral.
 *   - If activity IS observed here (clean, expected-looking SCL/SDA
 *     transitions) but the real I2C1 hardware driver
 *     (bk7258_i2c1_write_reg()) still times out: the pins themselves are
 *     fine, and the problem is specific to the I2C1 hardware block's
 *     interrupt/state-machine path or the GC2145 sensor not responding
 *     electrically (e.g. not powered).
 *
 * This is a one-shot diagnostic, not a general-purpose bit-banged I2C
 * driver: it does not read ACK, does not implement STOP correctly per
 * I2C spec nuances, and is not intended to actually talk to GC2145.  It
 * exists purely to produce observable, predictable waveforms for
 * external measurement.
 *
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

#include <nuttx/config.h>
#include <nuttx/arch.h>

#include <stdio.h>
#include <stdint.h>

#include "bk7258_gpio.h"

/* Must match bk7258_i2c1.c's pin assignment exactly, so this diagnostic
 * is measuring the same physical pins the real driver uses. */
#define BK7258_I2C1_DIAG_SCL_PIN  42u
#define BK7258_I2C1_DIAG_SDA_PIN  43u

/* Slow, easily-observable timing: 500us per half-bit-cell, i.e. roughly
 * 1kHz -- far below the real driver's 100kHz, deliberately, so that even
 * a low-sample-rate logic analyzer or a hand-held oscilloscope probe can
 * catch every transition without needing to trigger precisely. */
#define BK7258_I2C1_DIAG_DELAY_US 500u

static void diag_delay(void)
{
  up_udelay(BK7258_I2C1_DIAG_DELAY_US);
}

/* Reconfigure the pins as plain push-pull GPIO outputs (function=1,
 * matching this board's GPIO_DEV_MAP convention where index 0 is the
 * peripheral function (I2C1_SCL/I2C1_SDA) and other indices are other
 * alternate functions/GPIO -- bk7258_gpio_output() itself already clears
 * BK7258_GPIO_SECOND_FUNCTION, which is sufficient to route the pin back
 * to plain GPIO regardless of what function index was last selected by
 * bk7258_gpio_set_function(), so no explicit "set function to GPIO" call
 * is needed here beyond calling bk7258_gpio_output() itself). */
static void diag_pins_as_gpio(void)
{
  bk7258_gpio_output(BK7258_I2C1_DIAG_SCL_PIN, true);
  bk7258_gpio_output(BK7258_I2C1_DIAG_SDA_PIN, true);
}

/****************************************************************************
 * Name: bk7258_i2c1_gpio_diag
 *
 * Description:
 *   One-shot GPIO-level bit-bang diagnostic for GPIO42 (I2C1_SCL) and
 *   GPIO43 (I2C1_SDA).  Produces, in order:
 *     1. Idle high on both lines (bus idle state), held for 5 half-bit
 *        periods so a scope/analyzer has time to arm/trigger.
 *     2. An I2C START condition: SDA high->low while SCL stays high.
 *     3. 8 manual SCL clock pulses (simulating clocking out one byte),
 *        with SDA alternating 1/0 on each pulse (a 0xAA-like pattern,
 *        chosen for visually distinguishing individual bit cells on a
 *        capture).
 *     4. An I2C STOP-like condition: SDA low->high while SCL stays high.
 *     5. Idle high on both lines.
 *   Prints each phase to the console so the log timestamps can be
 *   correlated with a capture's time axis.
 *
 ****************************************************************************/

int bk7258_i2c1_gpio_diag(int argc, char **argv)
{
  int i;

  printf("i2c1_gpio_diag: reconfiguring GPIO%u/GPIO%u as plain GPIO "
         "outputs (undoing I2C1 pinmux)\n",
         BK7258_I2C1_DIAG_SCL_PIN, BK7258_I2C1_DIAG_SDA_PIN);
  diag_pins_as_gpio();

  printf("i2c1_gpio_diag: idle high, 5 periods\n");
  for (i = 0; i < 5; i++)
    {
      diag_delay();
    }

  printf("i2c1_gpio_diag: START condition (SDA falls while SCL high)\n");
  bk7258_gpio_write(BK7258_I2C1_DIAG_SDA_PIN, false);
  diag_delay();
  bk7258_gpio_write(BK7258_I2C1_DIAG_SCL_PIN, false);
  diag_delay();

  printf("i2c1_gpio_diag: clocking out 8 bits (alternating 1/0 pattern)\n");
  for (i = 0; i < 8; i++)
    {
      bk7258_gpio_write(BK7258_I2C1_DIAG_SDA_PIN, (i % 2) == 0);
      diag_delay();
      bk7258_gpio_write(BK7258_I2C1_DIAG_SCL_PIN, true);
      diag_delay();
      bk7258_gpio_write(BK7258_I2C1_DIAG_SCL_PIN, false);
      diag_delay();
    }

  bk7258_gpio_write(BK7258_I2C1_DIAG_SDA_PIN, false);
  diag_delay();

  printf("i2c1_gpio_diag: STOP condition (SCL rises, then SDA rises)\n");
  bk7258_gpio_write(BK7258_I2C1_DIAG_SCL_PIN, true);
  diag_delay();
  bk7258_gpio_write(BK7258_I2C1_DIAG_SDA_PIN, true);
  diag_delay();

  printf("i2c1_gpio_diag: idle high, done -- measure GPIO%u (SCL) and "
         "GPIO%u (SDA) now\n",
         BK7258_I2C1_DIAG_SCL_PIN, BK7258_I2C1_DIAG_SDA_PIN);

  return 0;
}

