/************************************************************************************
 *
 * Basic I2C Bus signal.
 *     START, STOP, ACK, No ACK.
 * Pull down SCL line before return from any routines here.
 ************************************************************************************/

#define I2C_PIN_DELAY()		I2cDelay(0)

static inline void I2cSclPulse()
{
	I2cSetSclHigh();
	I2cDelay(SCL_DELAY);

	I2cSetSclLow();

{
	I2cSetSclHigh();
	I2cDelay(SCL_DELAY);

	I2cSetSclLow();
	I2cDelay(SCL_DELAY);
}

static void I2cSclPulse_ack()
{
	I2cSetSclHigh();
	I2cDelay(SCL_DELAY);

	I2cSetSclLow();
	I2cSetSdaInput();
	I2cDelay(SCL_DELAY);
}

static void I2cStart(void)
{
	// Just to ensure SCL is in LOW state.
//	I2cSetSclLow();
//	I2cDelay(SCL_HALF_DELAY);

	I2cSetSdaOutput();
	I2C_PIN_DELAY();

	// SDA SCL in HIGH state
	I2cSetSdaHigh();
	I2C_PIN_DELAY();

	I2cSetSclHigh();
	I2cDelay(SCL_DELAY);

	// A HIGH to LOW transition on the SDA line while SCL is HIGH
	I2cSetSdaLow();
	I2cDelay(MAX(SCL_HALF_DELAY, I2C_MIN_DELAY));

	// to default state.
	I2cSetSclLow();
	I2cDelay(SCL_DELAY);
}

static void I2cStop(void)
{
	// Just to ensure SCL is in LOW state.
	I2cSetSclLow();
	I2cDelay(SCL_HALF_DELAY);

	// SDA in LOW state, SCL in HIGH state
	I2cSetSdaLow();
	I2C_PIN_DELAY();

	I2cSetSclHigh();
	I2cDelay(SCL_DELAY);

	// A LOW to HIGH transition on the SDA line while SCL is HIGH
	I2cSetSdaHigh();
	I2cDelay(SCL_DELAY);

	// to default state.
	/*
	I2cSetSclLow();
	I2cDelay(SCL_DELAY);
	*/ // should discard these codes for multi-master I2C bus.( or new devices of latest protocol. )
}

static inline void I2cAck(void)
{
	// Pull down SDA line.
	I2cSetSdaLow();
	I2C_PIN_DELAY();

	I2cSclPulse();
}

static inline void I2cNoAck(void)
{
	// let SDA line in HIGH state during ACK clock cycle.
	I2cSetSdaHigh();
	I2C_PIN_DELAY();

	I2cSclPulse();
}

