/****************************************************************************
 * board/beken/chips/bk7258/bk7258_i2c1.c
 *
 * Software bit-banged (GPIO simulated) I2C master-write driver for the
 * GC2145 camera sensor, on GPIO42 (SCL) / GPIO43 (SDA).
 *
 * IMPORTANT CORRECTION (see this file's previous revision history and
 * hardware/bk7258_i2c1.h for the full account): this board's GC2145
 * camera I2C bus is NOT the BK7258's hardware I2C1 peripheral, despite
 * GPIO42/43 supporting an I2C1_SCL/I2C1_SDA hardware pinmux function
 * (GPIO_DEV_I2C1_SCL/GPIO_DEV_I2C1_SDA in bk_avdk_smp's gpio_map.h).
 * That hardware-I2C1 assumption was this driver's original (incorrect)
 * design: on real hardware, every write timed out waiting for the I2C1
 * peripheral's sm_int interrupt, even though sm_bus_cfg read back
 * exactly as configured -- consistent with "the peripheral's dedicated
 * state machine is talking to a bus GC2145 was never wired to respond
 * on this way."
 *
 * Cross-checked against the two OpenVela-external reference projects
 * that actually target this exact AIDK board (beken_genie and volc_rtc,
 * both under bk_solution_ai/projects/, both linking the same
 * AIDK_AI玩具开发板_原理图.pdf as their hardware reference) rather than
 * the generic dvp_example project (whose default GPIO0/1 wiring this
 * board does not use -- GPIO0/1 are UART1_TXD/RXD here, per the
 * schematic and usr_gpio_cfg.h's GPIO_DEFAULT_DEV_CONFIG):
 *
 *   - Both beken_genie and volc_rtc override the *software-simulated*
 *     I2C0 instance's GPIO Kconfig options (CONFIG_SIM_I2C0_SCL_GPIO=42,
 *     CONFIG_SIM_I2C0_SDA_GPIO=43) -- i.e. GPIO42/43 ARE the correct
 *     physical pins, but the intended access method is bk_avdk_smp's
 *     sim_i2c_driver.c software bit-bang (CONFIG_DVP_CAMERA_I2C_ID=2,
 *     which ap/middleware/driver/i2c/i2c_unified.c routes to "GPIO
 *     simulated I2C (starting from I2C_ID_2)", i.e. NOT any hardware
 *     I2C unit), not the hardware I2C1 register block this driver
 *     originally used.
 *   - Both projects' usr_gpio_cfg.h leave GPIO42/43's *static* default
 *     function as GPIO_DEV_LCD_G2/GPIO_DEV_LCD_B7 (an RGB LCD data-line
 *     use this board does not actually populate), confirming the pins
 *     are NOT meant to be pinmux-selected to their I2C1_SCL/I2C1_SDA
 *     hardware function at all -- sim_i2c_driver.c's bk_i2c_init_v2()
 *     explicitly calls gpio_dev_unmap() on both pins before bit-banging
 *     them as plain GPIO, which is the actual, correct access pattern
 *     this file now follows.
 *   - Those same two projects confirm the real gyroscope (SC7A20H, this
 *     board's actual U6/IIC1_SCL+IIC1_SDA-labelled schematic net) is
 *     wired to the *hardware* I2C0 peripheral on GPIO20/21
 *     (GPIO_DEV_I2C0_SCL/GPIO_DEV_I2C0_SDA in usr_gpio_cfg.h, matching
 *     bk_avdk_smp's own gsensor_sc7a20.c reference driver, which hard-
 *     codes GPIO_20/GPIO_21 via I2C_ID_0) -- i.e. this board's schematic
 *     net label "IIC1" is the gyroscope's bus, and has nothing to do
 *     with this driver's GPIO42/43 camera bus, despite both being
 *     labelled with a "1" digit in different places (schematic net name
 *     vs. hardware peripheral index) that turned out not to refer to
 *     the same thing. See the board's docs/README schematic pointer and
 *     AIDK_AI玩具开发板_原理图.pdf sheet 2/6 (chip pinout) + sheet 4/6
 *     (gyroscope + DVP camera connector) for the underlying schematic
 *     evidence this correction is based on.
 *
 * Protocol/timing ported from bk_avdk_smp's
 * ap/middleware/driver/i2c/sim_i2c_driver.c (I2cStart/I2cStop/I2cSend/
 * I2cWrite/I2cMemWrite and their SCL_DELAY busy-wait spin timing), which
 * is itself the implementation CONFIG_DVP_CAMERA_I2C_ID=2 resolves to
 * for every bk_avdk_smp project using I2C_ID_2 (i.e. this is not a
 * one-off reimplementation choice -- it is the same code path the
 * reference SDK itself uses for this exact purpose). Reimplemented here
 * against this repo's bk7258_gpio.h primitives
 * (bk7258_gpio_output()/bk7258_gpio_write()/bk7258_gpio_read()) rather
 * than sim_i2c_driver.c's direct SOC_AON_GPIO_REG_BASE register pokes,
 * since those primitives already exist in this codebase and provide
 * the same net effect (direct, unbuffered GPIO level control, no RTOS
 * scheduling latency injected between consecutive bit-cells).
 *
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

#include <nuttx/config.h>
#include <nuttx/arch.h>

#include <stdbool.h>
#include <stdint.h>

#include "bk7258_gpio.h"
#include "bk7258_i2c1.h"

/* GPIO42/GPIO43: plain GPIO bit-bang, NOT the I2C1_SCL/I2C1_SDA hardware
 * pinmux function -- see this file's header comment.  No
 * bk7258_gpio_set_function() call is made for either pin: leaving them
 * at their default/static function (whatever board bring-up left them
 * as, e.g. GPIO_DEV_LCD_G2/GPIO_DEV_LCD_B7 in the reference projects'
 * static tables) is fine because bk7258_gpio_output()/
 * bk7258_gpio_write() below unconditionally clear
 * BK7258_GPIO_SECOND_FUNCTION on every call, which is this repo's
 * equivalent of sim_i2c_driver.c's explicit gpio_dev_unmap() calls in
 * bk_i2c_init_v2(). */
#define BK7258_I2C1_SCL_PIN       42u
#define BK7258_I2C1_SDA_PIN       43u

/* Busy-wait spin count per SCL half-period.  sim_i2c_driver.c's
 * SCL_DELAY for 100kHz (CLK_DELAY_100K=25) is calibrated for that SDK's
 * own busy-wait loop body and CPU clock, which do not necessarily match
 * this NuttX build's optimization level or up_udelay() call overhead;
 * using up_udelay() with an explicit microsecond value instead of a
 * bare spin count is more portable across compilers/optimization
 * levels, at the cost of being slower than a tightly-tuned spin loop.
 * 5us per half-period is standard-mode I2C's *minimum* SCL high/low
 * time (100kHz nominal = 5us half-period exactly); GC2145 is not
 * timing-critical beyond standard-mode I2C compliance, so exact
 * matching to the reference driver's spin count is not required. */
#define BK7258_I2C1_HALF_PERIOD_US  5u

static void bk7258_i2c1_delay(void)
{
  up_udelay(BK7258_I2C1_HALF_PERIOD_US);
}

static void bk7258_i2c1_scl_high(void)
{
  bk7258_gpio_output(BK7258_I2C1_SCL_PIN, true);
}

static void bk7258_i2c1_scl_low(void)
{
  bk7258_gpio_output(BK7258_I2C1_SCL_PIN, false);
}

static void bk7258_i2c1_sda_high(void)
{
  bk7258_gpio_output(BK7258_I2C1_SDA_PIN, true);
}

static void bk7258_i2c1_sda_low(void)
{
  bk7258_gpio_output(BK7258_I2C1_SDA_PIN, false);
}

/* Release SDA to input (with the board's external 4.7K pull-up doing
 * the "release high" work, per this file's header comment on this
 * board's schematic-provided pull-ups) so this master can sample the
 * slave's ACK/NACK response during the 9th clock cycle -- matching
 * sim_i2c_driver.c's I2cSetSdaInput() before I2cReadSda(). */
static void bk7258_i2c1_sda_release(void)
{
  bk7258_gpio_input_pullup(BK7258_I2C1_SDA_PIN);
}

static bool bk7258_i2c1_sda_read(void)
{
  return bk7258_gpio_read(BK7258_I2C1_SDA_PIN);
}

/* I2C START condition: SDA high-to-low transition while SCL is high.
 * Matches sim_i2c_driver.c's I2cStart(). */
static void bk7258_i2c1_start(void)
{
  bk7258_i2c1_sda_high();
  bk7258_i2c1_delay();

  bk7258_i2c1_scl_high();
  bk7258_i2c1_delay();

  bk7258_i2c1_sda_low();
  bk7258_i2c1_delay();

  bk7258_i2c1_scl_low();
  bk7258_i2c1_delay();
}

/* I2C STOP condition: SDA low-to-high transition while SCL is high.
 * Matches sim_i2c_driver.c's I2cStop(). */
static void bk7258_i2c1_stop(void)
{
  bk7258_i2c1_scl_low();
  bk7258_i2c1_delay();

  bk7258_i2c1_sda_low();
  bk7258_i2c1_delay();

  bk7258_i2c1_scl_high();
  bk7258_i2c1_delay();

  bk7258_i2c1_sda_high();
  bk7258_i2c1_delay();
}

/* Clock out one bit (MSB-first) and pulse SCL, matching
 * sim_i2c_driver.c's per-bit loop inside I2cSend(). */
static void bk7258_i2c1_write_bit(bool bit_value)
{
  if (bit_value)
    {
      bk7258_i2c1_sda_high();
    }
  else
    {
      bk7258_i2c1_sda_low();
    }

  bk7258_i2c1_delay();

  bk7258_i2c1_scl_high();
  bk7258_i2c1_delay();

  bk7258_i2c1_scl_low();
  bk7258_i2c1_delay();
}

/* Send one byte, MSB-first, then release SDA and sample the slave's ACK
 * bit on the 9th clock.  Returns true if the slave pulled SDA low
 * (ACK), false on NACK (SDA stayed high) -- matching sim_i2c_driver.c's
 * I2cSend() return value convention. */
static bool bk7258_i2c1_send_byte(uint8_t data)
{
  int bit;
  bool acked;

  for (bit = 7; bit >= 0; bit--)
    {
      bk7258_i2c1_write_bit((data & (1u << bit)) != 0);
    }

  bk7258_i2c1_sda_release();
  bk7258_i2c1_delay();

  bk7258_i2c1_scl_high();
  bk7258_i2c1_delay();

  acked = !bk7258_i2c1_sda_read();

  bk7258_i2c1_scl_low();
  bk7258_i2c1_delay();

  /* Drive SDA again (it was left in input/released state above) before
   * the next write_bit()/stop() call assumes output control -- matches
   * sim_i2c_driver.c's I2cSend() calling I2cSetSdaOutput() right after
   * sampling ACK, for the same reason (I2cSetSdaHigh/Low() alone do not
   * return the pin to output mode once it has been released to input
   * for the ACK sample). */
  bk7258_i2c1_sda_high();

  return acked;
}

void bk7258_i2c1_init(void)
{
  /* No clock-gate/pinmux/interrupt setup needed: this is plain GPIO
   * bit-banging, not the hardware I2C1 peripheral (see this file's
   * header comment).  Idle the bus (both lines high) so the first
   * bk7258_i2c1_write_reg() call's START condition begins from a clean
   * idle state, matching sim_i2c_driver.c's I2cInit() (SetSdaOutput()
   * + SetSclOutput(), which this repo's bk7258_gpio_output(pin, true)
   * calls below achieve directly by driving both pins high). */
  bk7258_i2c1_sda_high();
  bk7258_i2c1_scl_high();
}

bool bk7258_i2c1_write_reg(uint8_t i2c_addr, uint8_t reg, uint8_t value)
{
  bool acked;

  bk7258_i2c1_start();

  acked = bk7258_i2c1_send_byte((uint8_t)(i2c_addr << 1));
  if (!acked)
    {
      bk7258_i2c1_stop();
      return false;
    }

  acked = bk7258_i2c1_send_byte(reg);
  if (!acked)
    {
      bk7258_i2c1_stop();
      return false;
    }

  acked = bk7258_i2c1_send_byte(value);

  bk7258_i2c1_stop();

  return acked;
}

